import React, { useState, useMemo, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import NavBar from '../Components/NavBar'
import Footer from '../Components/Footer'
import './advertisements.css'

// IMPORTANT: Ensure these files exist in your public/Images folder:
// /Images/t-shirt-course.jpeg
// /Images/home2.jpeg

const posters = [
  {
    id: 1,
    title: 'T-shirt සැකසීමේ වැඩමුළුව',
    images: [
      '/Images/t-shirt-course.jpeg',
      '/Images/t-shirt-course-1.jpeg', // Added a second image for demonstration
      '/Images/t-shirt-course-2.jpeg',
      '/Images/t-shirt-course-3.jpeg',
      '/Images/t-shirt-course-4.jpeg',
      '/Images/t-shirt-course-5.jpeg',
      '/Images/t-shirt-course-6.jpeg',
    ],
    description: `
      🔹 මුල සිට සරලවම T-shirt පතොරම් සකස්කර ගැනීමේ ක්‍රමවේදය  
      • අවශ්‍ය පතොරම් ලබා ගැනීම  
      • සමාජ මාධ්‍ය හරහා අලෙවි කරන ආකාරය  
      • AI භාවිතයෙන් පින්තූර සැකසීම  
      • ඩිජිටල් අලෙවිකරණය/marketing  
      • Screen printing හැදෑරීම  
      • DTF printing හැදෑරීම  
      • මිල ගණනය කරන ක්‍රමවේදය  
      • Size chart පිළිබඳව දැනගැනීම  
      • FaceBook ad boost කිරීම  
      මෙම වැඩමුළුව තුළ ඔබට T-shirt brand එකක් තැනගැනීමේ සම්පූර්ණ මොර්ගය මෙරීනම් කොටස් හා පියවරෙන් පියවර ඉදිරිපත් කරනු ලැබේ.
      `.trim(),
  },
  {
    id: 2,
    title: 'බතික් පාඨමාලාව',
    images: [
      '/Images/bathic-1.jpeg',
      '/Images/bathic-2.jpeg',
      '/Images/bathic-3.jpeg',
      '/Images/bathic-4.jpeg',
      '/Images/bathic-5.jpeg',
      '/Images/bathic-6.jpeg',
    ],
    description: `
          • බතික් භාවිතා කර ටී ෂර්ට් සහ නිකුත් ඇඳුම් වර්ණ ගැන්වීම 
          • ඉටි භාවිතා කර බතික් කිරීම සහ ටයි ඇන්ඩයි න් සිදුකර අගය එකතුකරෙන් පිළිබඳව මෙම වැඩමුළුවේදී සාකච්ඡා කෙරේ
          • reactive Dye
          • Tie and Dye 
          • Java Batik
          • Itty Batik 
        `.trim(),
  },
  {
    id: 3,
    title: 'Screen printing පාඨමාලාව',
    images: [
      '/Images/sp-1.jpeg',
      '/Images/sp-2.jpeg',
      '/Images/sp-3.jpeg',
      '/Images/sp-4.jpeg',
      '/Images/sp-5.jpeg',
      '/Images/sp-6.jpeg',
    ],
    description: `
      • තින්ත් භාවිතය 
      • ප්‍රින්ටින් සඳහා ස්ක්‍රීන් එකක් සැකසීම 
      • ප්‍රින්ට් කිරීමට ප්‍රථම සැලකිලිමත් විය යුතු කරුණු 
      • Puff Printing 
      • 1 Color Print 
      • 3 Color Print 
      • 4 Color Print 
      • Glitter Printing 
      • Color Separation 
      • ARTWORK සකස් කිරීම 
      • එක් දින අංග සම්පූර්ණ වැඩමුළුව 
      මෙම පාඨමාලාව තුළ ඔබට වර්ණ බහුල/පෞද්ගලික නිෂ්පාදන සදහා අවශ්‍ය හැමදේම ඉගෙනගත හැක.
    `.trim(),
  },
]

const courseOptions = [
  { name: 'T-Shirt Course', price: 1500, key: 'courseTshirt' },
  { name: 'Batik Course', price: 2000, key: 'courseBatik' },
  { name: 'Screen Printing Course', price: 2500, key: 'courseScreen' },
]

const itemOptions = [
  { name: 'T-shirts සඳහා පතොරම් 3ක කට්ටලය(Ladies t-shirt, Unisex t-shirt, Crop top t-shirt)', price: 500, key: 'itemBook' },
  { name: 'T-shirts සඳහා පතොරම් 5ක කට්ටලය(Ladies t-shirt, Unisex t-shirt, Crop top t-shirt, Baggy t-shirt, Drop shoulder t-shirt)', price: 1000, key: 'itemVideo' },
  { name: 'T-shirt 3 Pattern Set', price: 800, key: 'itemPatternSet' },
  { name: 'Starter Ink Kit', price: 700, key: 'itemInkKit' },
]

// Target WhatsApp Number
const WHATSAPP_NUMBER = '94703755312'; // Must include country code without '+'

// --- NEW FADE SLIDESHOW COMPONENT ---
function FadeSlideshow({ images, interval = 3000 }) {
  const [currentIndex, setCurrentIndex] = useState(0)
  
  useEffect(() => {
    // Set up the automatic transition
    const timer = setInterval(() => {
      setCurrentIndex(prevIndex => (prevIndex + 1) % images.length)
    }, interval)

    // Clean up the interval when the component unmounts or images change
    return () => clearInterval(timer)
  }, [images.length, interval])

  if (images.length === 0) {
    return <div className="slideshow-error">No images provided.</div>
  }

  return (
    <div className="slideshow-container">
      {images.map((imageSrc, index) => (
        <img
          key={index}
          src={imageSrc}
          alt={`Slide ${index + 1}`}
          // Use a className to manage the fade transition in CSS
          className={`slideshow-image ${index === currentIndex ? 'active' : ''}`}
          draggable={false}
          // Note: Error handling for individual images is removed for simplicity
          // but could be added back if needed.
        />
      ))}
    </div>
  )
}
// --- END NEW FADE SLIDESHOW COMPONENT ---


export default function Advertisements() {
  const navigate = useNavigate()
  // NOTE: goToDetail is kept but not used anymore for navigation
  const goToDetail = (poster) => {
      // You can use this function if you re-enable navigation later
      // navigate(`/advertisement/${poster.id}`, { state: poster })
      console.log(`Poster clicked: ${poster.title}`);
  }

  // --- Form State Management ---
  const [participateChecked, setParticipateChecked] = useState(false)
  const [selections, setSelections] = useState({
    courseTshirt: false,
    courseBatik: false,
    courseScreen: false,
    itemBook: false,
    itemVideo: false,
    itemPatternSet: false,
    itemInkKit: false,
  })
  const [userDetails, setUserDetails] = useState({
    name: '',
    email: '',
    phone: ''
  })

  // --- Handlers ---
  const handleSelectionChange = (key) => {
    setSelections(prev => ({
      ...prev,
      [key]: !prev[key]
    }))
  }

  const handleUserDetailChange = (e) => {
    setUserDetails(prev => ({
      ...prev,
      [e.target.name]: e.target.value
    }))
  }

  // --- Calculation Logic ---
  const calculatedTotal = useMemo(() => {
    let total = 0
    courseOptions.forEach(option => {
      if (selections[option.key]) {
        total += option.price
      }
    })
    itemOptions.forEach(option => {
      if (selections[option.key]) {
        total += option.price
      }
    })
    return total
  }, [selections])

  // --- WhatsApp URL Generator ---
  const generateWhatsAppUrl = (total) => {
    const selectedCourses = courseOptions
      .filter(option => selections[option.key])
      .map(option => `\t- ${option.name} (LKR ${option.price})`).join('\n')
    const selectedItems = itemOptions
      .filter(option => selections[option.key])
      .map(option => `\t- ${option.name} (LKR ${option.price})`).join('\n')

    let messageBody = `
*NEW COURSE REGISTRATION*\n
*Personal Details:*\n
\tName: ${userDetails.name}
\tEmail: ${userDetails.email}
\tPhone: ${userDetails.phone}
\n
*Selected Courses:*
${selectedCourses || '\t(No courses selected)'}
\n
*Selected Items:*
${selectedItems || '\t(No items selected)'}
\n
*TOTAL FEE: LKR ${total.toFixed(2)}*\n
    `.trim()

    return `https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(messageBody)}`
  }

  const handleSubmit = (e) => {
    e.preventDefault()
    if (calculatedTotal === 0) {
      alert("Please select at least one course or item to register.")
      return
    }
    // Basic validation
    if (!userDetails.name || !userDetails.email || !userDetails.phone) {
        alert("Please fill in all personal details (Name, Email, Phone) before submitting.");
        return;
    }
    
    const whatsappLink = generateWhatsAppUrl(calculatedTotal)
    window.open(whatsappLink, '_blank')
  }

  const renderCheckboxes = (options, title) => (
    <div className="form-group">
      <h3 className="form-subtitle">{title}</h3>
      {options.map((option) => (
        <label key={option.key} className="checkbox-label">
          <input
            type="checkbox"
            checked={selections[option.key]}
            onChange={() => handleSelectionChange(option.key)}
          />
          {option.name} <span className="item-price"> (LKR {option.price})</span>
        </label>
      ))}
    </div>
  )

  return (
    <div className="advertisements-page">
      <NavBar />

      <main className="content-area">
        <header className="page-header">
          <h1>Creative Workshops & Courses 🎨</h1>
          <p>Explore a range of hands-on courses in textile design and printing!</p>
        </header>

        <section className="posters-grid">
          {posters.map((poster) => (
            <article
              key={poster.id}
              className="poster-card"
              // Removed onClick={() => goToDetail(poster)} to disable navigation
            >
              <div className="poster-image-wrapper">
                {/* Replaced ImageCarousel with FadeSlideshow */}
                <FadeSlideshow images={poster.images} /> 
              </div>
              <div className="poster-info">
                <h3 className="poster-title">{poster.title}</h3>
                <p className="poster-description">
                  {poster.description.split('\n').map((line, idx) => {
                    const cleanLine = line.trim();
                    if (cleanLine.startsWith('🔹') || cleanLine.startsWith('•')) {
                      return <span key={idx}><br />{cleanLine}</span>
                    }
                    return <span key={idx}>{cleanLine}<br /></span>
                  })}
                </p>
              </div>
            </article>
          ))}
        </section>

        <section className="registration-section">
          <h2 className="section-title">Course Registration</h2>

          <div className="participate-toggle">
            <label className="checkbox-label participate-label">
              <input
                type="checkbox"
                checked={participateChecked}
                onChange={() => setParticipateChecked(!participateChecked)}
              />
              Aromi fashion academy විසින් පවත්වන ඉතා වැදගත් වැඩමුළුව සඳහා අදම ලියාපදිංචි වන්න.
            </label>
          </div>

          {participateChecked && (
            <form onSubmit={handleSubmit} className="registration-form">
              <div className="form-selection-group">
                {renderCheckboxes(courseOptions, 'Select the Course')}
                <div className="form-divider"></div>
                {renderCheckboxes(itemOptions, 'I want to buy')}
              </div>

              <div className="total-value-box">
                Total Value: <span className="total-amount">LKR {calculatedTotal.toFixed(2)}</span>
              </div>

              <div className="form-divider"></div>

              <div className="personal-details-group">
                <h3 className="form-subtitle">Personal Details</h3>
                <input
                  type="text"
                  name="name"
                  placeholder="Full Name"
                  value={userDetails.name}
                  onChange={handleUserDetailChange}
                  required
                />
                <input
                  type="email"
                  name="email"
                  placeholder="Email Address"
                  value={userDetails.email}
                  onChange={handleUserDetailChange}
                  required
                />
                <input
                  type="tel"
                  name="phone"
                  placeholder="Phone Number (e.g., 07XXXXXXXX)"
                  value={userDetails.phone}
                  onChange={handleUserDetailChange}
                  required
                />
              </div>

              <button type="submit" className="submit-btn">
                Register & Send via WhatsApp 📲
              </button>
            </form>
          )}
        </section>
      </main>
      <Footer />
    </div>
  )
}
